'use client';

import React, { useState } from 'react';
import styles from './login.module.css';
import { Mail, ShieldCheck, ArrowRight, Loader2 } from 'lucide-react';

export default function AdminLogin() {
    const [email, setEmail] = useState('');
    const [otp, setOtp] = useState('');
    const [step, setStep] = useState(1); // 1: Email, 2: OTP
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleRequestOTP = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');
        try {
            const res = await fetch('/api/auth/otp', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email }),
            });
            const contentType = res.headers.get('content-type');
            let data;
            if (contentType && contentType.includes('application/json')) {
                data = await res.json();
            } else {
                const text = await res.text();
                throw new Error(`Server error (${res.status}): ${text.slice(0, 100)}`);
            }

            if (data.success) {
                setStep(2);
            } else {
                setError(data.error);
            }
        } catch (err: any) {
            setError(err.message || 'Network error. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleVerifyOTP = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');
        try {
            const res = await fetch('/api/auth/verify', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, otp }),
            });
            const contentType = res.headers.get('content-type');
            let data;
            if (contentType && contentType.includes('application/json')) {
                data = await res.json();
            } else {
                const text = await res.text();
                throw new Error(`Server error (${res.status}): ${text.slice(0, 100)}`);
            }

            if (data.success) {
                // Redirect to dashboard
                window.location.href = '/admin/dashboard';
            } else {
                setError(data.error);
            }
        } catch (err: any) {
            setError(err.message || 'Network error. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className={styles.container}>
            <div className={styles.loginCard}>
                <div className={styles.iconWrapper}>
                    <ShieldCheck size={48} color="var(--primary-deep-blue)" />
                </div>
                <h1>Admin Portal</h1>
                <p className={styles.subtitle}>Enter your details to access the dashboard</p>

                {error && <div className={styles.error}>{error}</div>}

                {step === 1 ? (
                    <form onSubmit={handleRequestOTP} className={styles.form}>
                        <div className={styles.inputGroup}>
                            <Mail size={20} className={styles.inputIcon} />
                            <input
                                type="email"
                                placeholder="Admin Email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                required
                            />
                        </div>
                        <button type="submit" className={styles.submitBtn} disabled={isLoading}>
                            {isLoading ? <Loader2 className={styles.spinner} /> : 'Send OTP'}
                            {!isLoading && <ArrowRight size={18} />}
                        </button>
                    </form>
                ) : (
                    <form onSubmit={handleVerifyOTP} className={styles.form}>
                        <p className={styles.infoText}>OTP sent to <strong>{email}</strong></p>
                        <div className={styles.inputGroup}>
                            <ShieldCheck size={20} className={styles.inputIcon} />
                            <input
                                type="text"
                                placeholder="6-Digit OTP"
                                maxLength={6}
                                value={otp}
                                onChange={(e) => setOtp(e.target.value)}
                                required
                            />
                        </div>
                        <button type="submit" className={styles.submitBtn} disabled={isLoading}>
                            {isLoading ? <Loader2 className={styles.spinner} /> : 'Verify & Login'}
                        </button>
                        <button
                            type="button"
                            className={styles.backBtn}
                            onClick={() => setStep(1)}
                            disabled={isLoading}
                        >
                            Back to Email
                        </button>
                    </form>
                )}
            </div>
        </div>
    );
}
